func TestEngine_Execute_Accept(t *testing.T) {
	tmpDir := t.TempDir()
	scriptContent := `
function handle(req, env) {
    if (req.method !== "POST") {
        return { accept: false, status: 405, error: "Method not allowed" };
    }
    return { accept: true };
}
`
	scriptPath := filepath.Join(tmpDir, "test_accept.js")
	if err := os.WriteFile(scriptPath, []byte(scriptContent), 0644); err != nil {
		t.Fatalf("failed to write script: %v", err)
	}

	eng := New(tmpDir)
	res, err := eng.Execute(context.Background(), scriptPath, nil, RequestData{
		Method: "POST",
		Path:   "/v1/ingest/test",
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !res.Accept {
		t.Errorf("expected accept: true, got false")
	}
}

