func TestEngine_AgnosticCryptoPrimitives(t *testing.T) {
	tmpDir := t.TempDir()

	// Build a valid encrypted payload:
	// IV (16 bytes) + HMAC-SHA256 (32 bytes) + AES-128-CBC encrypted timestamp
	token := "secret_key_12345"
	key := token[:16]

	iv := []byte("0123456789abcdef")
	timestamp := fmt.Sprintf("%d", time.Now().Unix())

	// Pad plaintext with PKCS#7
	plaintext := []byte(timestamp)
	padding := aes.BlockSize - (len(plaintext) % aes.BlockSize)
	padtext := bytes.Repeat([]byte{byte(padding)}, padding)
	paddedPlaintext := append(plaintext, padtext...)

	block, _ := aes.NewCipher([]byte(key))
	ciphertext := make([]byte, len(paddedPlaintext))
	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(ciphertext, paddedPlaintext)

	// Calculate HMAC of ciphertext
	mac := hmac.New(sha256.New, []byte(token))
	mac.Write(ciphertext)
	hmacBytes := mac.Sum(nil)

	// Combine: IV + HMAC + Ciphertext
	combined := append(iv, hmacBytes...)
	combined = append(combined, ciphertext...)
	signatureBase64 := base64.StdEncoding.EncodeToString(combined)

	scriptContent := `
function handle(req, env) {
    var token = env.TOKEN;
    var sig = req.body;

    var iv = crypto.sliceBase64(sig, 0, 16);
    var hmacExpected = crypto.sliceBase64(sig, 16, 48);
    var ciphertext = crypto.sliceBase64(sig, 48);

    var calcmac = crypto.hmacSha256Base64(token, ciphertext);
    if (!crypto.timingSafeEqual(hmacExpected, calcmac)) {
        return { accept: false, error: "HMAC mismatch" };
    }

    var decrypted = crypto.aes128CbcDecrypt(ciphertext, token, iv);
    var originalTime = parseFloat(decrypted);

    var diff = Math.abs(crypto.now() - originalTime);
    if (diff > 300) {
        return { accept: false, error: "Expired" };
    }

    return { accept: true };
}
`
	scriptPath := filepath.Join(tmpDir, "test_agnostic_crypto.js")
	if err := os.WriteFile(scriptPath, []byte(scriptContent), 0644); err != nil {
		t.Fatalf("failed to write script: %v", err)
	}

	eng := New(tmpDir)
	res, err := eng.Execute(context.Background(), scriptPath, map[string]string{"TOKEN": token}, RequestData{
		Body: signatureBase64,
	})
	if err != nil {
		t.Fatalf("execution error: %v", err)
	}
	if !res.Accept {
		t.Errorf("expected accept: true, got false. Error: %s", res.Error)
	}
}

